// Sanea el error antes de registrarlo. Nunca deja salir un secreto
// ni el contenido completo de un documento (docs/security.md §7).

const SECRET_PATTERNS = [
  { re: /[0-9]{8,10}:AA[A-Za-z0-9_-]{33}/g, tag: '[TOKEN_TELEGRAM]' },
  { re: /\bsk-[A-Za-z0-9_-]{20,}/g,          tag: '[API_KEY]' },
  { re: /\bAIza[A-Za-z0-9_-]{35}/g,          tag: '[API_KEY_GOOGLE]' },
  { re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, tag: '[CLAVE_PRIVADA]' },
  { re: /\bBearer\s+[A-Za-z0-9._-]{20,}/gi,  tag: '[BEARER]' },
  { re: /"(?:accessToken|apiKey|privateKey|password|secret)"\s*:\s*"[^"]*"/gi, tag: '"[REDACTADO]"' }
];

function sanear(texto) {
  if (texto === null || texto === undefined) return '';
  let s = String(texto);
  for (const { re, tag } of SECRET_PATTERNS) s = s.replace(re, tag);
  return s.slice(0, 900);
}

const e = $json.execution || {};
const w = $json.workflow || {};
const lastNode = e.lastNodeExecuted || 'desconocido';
const rawMsg = (e.error && (e.error.message || e.error.description)) || 'sin mensaje';

// Clasificación: define si se despierta al admin o solo se registra.
const msg = String(rawMsg).toLowerCase();
let nivel = 'error';
let notificarAdmin = true;

if (msg.includes('quota') || msg.includes('rate limit') || msg.includes('429')) {
  nivel = 'warn';
} else if (msg.includes('timeout') || msg.includes('etimedout') || msg.includes('econnreset')) {
  nivel = 'warn';
  notificarAdmin = false; // transitorio: el reintento suele resolverlo
}

// Un fallo de escritura en Sheets siempre despierta al admin: es el unico
// caso en que el usuario pudo quedar sin su movimiento registrado.
if (msg.includes('sheets') || msg.includes('spreadsheet')) {
  nivel = 'error';
  notificarAdmin = true;
}

const ahora = new Date();
const stamp = ahora.toISOString().slice(0, 10).replace(/-/g, '');
const rnd = Math.random().toString(36).slice(2, 6).toUpperCase();

return [{
  json: {
    evento_id: `EV-${stamp}-${rnd}`,
    timestamp: ahora.toISOString(),
    correlation_id: (e.error && e.error.context && e.error.context.correlation_id) || 'sin-correlacion',
    workflow: w.name || 'desconocido',
    ejecucion: String(e.id || ''),
    usuario: '',
    accion: 'error_no_controlado',
    resultado: nivel,
    detalle: `Fallo en el nodo "${lastNode}"`,
    error: sanear(rawMsg),
    datos_tecnicos: JSON.stringify({
      workflow_id: w.id || null,
      nodo: lastNode,
      modo: e.mode || null,
      url_ejecucion: e.url || null
    }),
    _notificar_admin: notificarAdmin,
    _nivel: nivel
  }
}];

// Arma el aviso tecnico. Texto corto: el admin lo lee en el celular.
const err = $('Sanear y Clasificar Error').first().json;
const cfg = $input.first().json || {};
const chatId = String(cfg.valor || '').trim();

if (!chatId) {
  // Sin admin_chat_id configurado no hay a quien avisar.
  // No es un fallo: se registro en Auditoria y con eso basta.
  return [];
}

const icono = err._nivel === 'error' ? '🔴' : '🟠';
const texto = [
  `${icono} Error en finanzas-telegram`,
  '',
  `Workflow: ${err.workflow}`,
  `Nodo: ${err.detalle.replace('Fallo en el nodo ', '')}`,
  `Ejecucion: ${err.ejecucion}`,
  `Evento: ${err.evento_id}`,
  '',
  `${err.error}`
].join('\n');

return [{ json: { chat_id: chatId, texto } }];

// Arma la fila en el orden EXACTO de columnas de 'Auditoria'.
const HEADERS = ["evento_id", "timestamp", "correlation_id", "workflow", "ejecucion", "usuario", "accion", "resultado", "detalle", "error", "datos_tecnicos"];
const item = $json;
const fila = HEADERS.map(h => item[h] !== undefined && item[h] !== null ? item[h] : '');
return { json: { fila } };
